  "Browsers signed in to your account. Tap ⋯ to name a device, see its sign-ins or sign it out. Connected agents are not listed here and keep working.": "आपके खाते में साइन इन ब्राउज़र। डिवाइस को नाम देने, उसके साइन-इन देखने या साइन आउट करने के लिए ⋯ दबाएँ। जुड़े एजेंट यहाँ नहीं दिखते और काम करते रहते हैं।",
