  "Button does nothing? Choose <b>Copy setup instead</b> and paste it into <code>~/.cursor/mcp.json</code> (create the file when missing).": "बटन से कुछ नहीं होता? <b>इसके बजाय सेटअप कॉपी करें</b> चुनें और उसे <code>~/.cursor/mcp.json</code> में पेस्ट करें (फ़ाइल न हो तो बना लें)।",
  "Button does nothing? Choose <b>Copy setup instead</b>, run <b>MCP: Open User Configuration</b> from the Command Palette and paste it there. VS Code uses <code>servers</code>, not <code>mcpServers</code>.": "बटन से कुछ नहीं होता? <b>इसके बजाय सेटअप कॉपी करें</b> चुनें, Command Palette से <b>MCP: Open User Configuration</b> चलाएँ और वहाँ पेस्ट करें। VS Code <code>servers</code> इस्तेमाल करता है, <code>mcpServers</code> नहीं।",
  "By": "द्वारा",
  "Call the Memora healthcheck tool, then search my memory for \"project\".": "Memora का healthcheck टूल चलाओ, फिर मेरी मेमोरी में \"project\" खोजो।",
