  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "अपने चुने हुए मॉडल से चैट करें; {mnemo} Memora के अपने टूल से नोट पढ़ता, लिखता, टैग करता, जोड़ता, ले जाता और व्यवस्थित करता है। वह वेब ब्राउज़ नहीं कर सकता, कमांड नहीं चला सकता, हमेशा के लिए नहीं हटा सकता और सर्वर नहीं बदल सकता। कुंजियाँ इस सर्वर पर सुरक्षित बंद रहती हैं और ब्राउज़र को कभी नहीं भेजी जातीं।",
  "Chat with your notes agent": "अपने नोट एजेंट से चैट करें",
  "ChatGPT only signs in over OAuth; it cannot send a key header.": "ChatGPT सिर्फ़ OAuth से साइन इन करता है; वह कुंजी हेडर नहीं भेज सकता।",
