  "Choose a new password. You can also change the username here.": "नया पासवर्ड चुनें। यहाँ यूज़रनेम भी बदल सकते हैं।",
  "Choose between 0.1 and 50 MB": "0.1 से 50 MB के बीच चुनें",
  "Choose from many languages in Settings, Appearance, per device. Auto follows your browser.": "सेटिंग्स, रूप-रंग में हर डिवाइस के लिए कई भाषाओं में से चुनें। ऑटो आपके ब्राउज़र का पालन करता है।",
  "Choose your vault folder": "अपना वॉल्ट फ़ोल्डर चुनें",
  "Chosen colour": "चुना हुआ रंग",
  "Chosen when it signs in": "साइन इन के समय चुना जाता है",
  "Claude Desktop (older)": "Claude Desktop (पुराना)",
  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude और ChatGPT आपके Memora खाते से साइन इन करते हैं। कुछ कॉपी करने की ज़रूरत नहीं।",
  "Claude models": "Claude मॉडल",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude OAuth से साइन इन करता है, इसलिए कुंजी पेस्ट नहीं करनी: अनुमति दें दबाने पर उसे अपनी कुंजी मिल जाती है। साइन-इन के बिना इसे <b>दूसरा ऐप</b> के रूप में जोड़ें और हेडर <code>Authorization: Bearer &lt;key&gt;</code> भेजें।",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor और बहुत कुछ",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor और बहुत कुछ, हर एक की अपनी कुंजी",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex और दूसरों को अलग-अलग एक्सेस मिलता है, ताकि आप देख सकें कि हर एक क्या करता है।",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT और आपका अपना एजेंट एक ही Memora साझा करते हैं, जो इस कंप्यूटर, लोकल नेटवर्क या इंटरनेट से पहुँच में है",
  "Claude, Cursor, ChatGPT and your own scripts read your notes and add to them.": "Claude, Cursor, ChatGPT और आपकी अपनी स्क्रिप्ट आपके नोट पढ़ती हैं और उनमें जोड़ती हैं।",
