  "Click <b>Add</b>, then <b>Connect</b>. A Memora page opens: sign in if asked and press <b>Allow</b>.": "<b>Add</b> पर क्लिक करें, फिर <b>Connect</b>। Memora का एक पेज खुलेगा: कहा जाए तो साइन इन करें और <b>Allow</b> दबाएँ।",
  "Click or tick tags to see their notes. Need more, like {example}? Use {button}": "टैग के नोट देखने के लिए उन पर क्लिक या टिक करें। और चाहिए, जैसे {example}? {button} इस्तेमाल करें",
