  "Deleted chats and their messages are gone for good. Your notes are not touched, and a chat that is answering right now is left alone.": "हटाई गई चैट और उनके संदेश हमेशा के लिए चले जाते हैं। आपके नोट को छुआ नहीं जाता, और जो चैट अभी जवाब दे रही है उसे छोड़ दिया जाता है।",
