  "Deleted notes wait here until you restore them or delete them forever. When you restore, you choose where the note goes: its old folder, another folder or the top level.": "हटाए गए नोट यहाँ तब तक रहते हैं जब तक आप उन्हें बहाल न करें या हमेशा के लिए न हटाएँ। बहाल करते समय आप चुनते हैं कि नोट कहाँ जाए: उसका पुराना फ़ोल्डर, दूसरा फ़ोल्डर या सबसे ऊपरी स्तर।",
