  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "डिस्क पर नोट ले जाने के लिए कार्ड को दूसरे फ़ोल्डर फ़्रेम में खींचें। बोर्ड सजाने के लिए फ़्रेम को उसके नाम से खींचें; पूरा फ़ोल्डर वहाँ ले जाने के लिए उसे दूसरे फ़्रेम पर छोड़ें। नाम बदलने के लिए शीर्षक पर डबल क्लिक करें। टच पर: खिसकाने के लिए खींचें, ज़ूम के लिए पिंच करें, कार्ड ले जाने के लिए देर तक दबाएँ, प्रीव्यू के लिए टैप करें।",
  "Drag a note here to pin it": "नोट पिन करने के लिए उसे यहाँ खींचें",
  "Drag notes or folders here to pin them": "पिन करने के लिए नोट या फ़ोल्डर यहाँ खींचें",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "नोट या फ़ोल्डर को फ़ोल्डर पर खींचें तो वे चले जाते हैं, पिन्ड पर खींचें तो पिन हो जाते हैं।",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "नोट खींचें · पिन के लिए डबल क्लिक · / खोज · #tag टैग खोजता है · F फ़िट · 1 2 3 लेआउट",
  "Drag to move the folder frame; double-click to rename": "फ़ोल्डर फ़्रेम ले जाने के लिए खींचें; नाम बदलने के लिए डबल क्लिक करें",
  "Drag to move the lane. Double click the name to rename it.": "कॉलम को हिलाने के लिए खींचें। नाम बदलने के लिए नाम पर डबल क्लिक करें।",
  "Drag to resize · double-click to reset": "आकार बदलने के लिए खींचें · रीसेट के लिए डबल क्लिक करें",
  "Drag to turn · scroll to zoom · click a point to open its note": "घुमाने के लिए खींचें · ज़ूम के लिए स्क्रोल करें · नोट खोलने के लिए बिंदु पर क्लिक करें",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "घुमाने के लिए खींचें · ज़ूम के लिए स्क्रोल करें · नोट खोलने के लिए बिंदु पर क्लिक करें · / खोज के लिए · #tag टैग खोजता है",
  "Draw a chart of how many notes I write each week": "एक चार्ट बनाओ कि मैं हर हफ़्ते कितने नोट लिखता हूँ",
  "Draw this note as a diagram": "इस नोट को डायग्राम के रूप में बनाओ",
  "Drop a card here or add one": "कार्ड यहाँ छोड़ें या नया जोड़ें",
