  "Each AI app connects over MCP with its own key and permissions.": "हर AI ऐप MCP पर अपनी कुंजी और अनुमतियों के साथ जुड़ता है।",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "आपका जोड़ा हर AI ऐप अपनी कुंजी वाला एजेंट है, इसलिए आप देखते हैं कि हर एक क्या करता है और किसी एक को अलग से बंद कर सकते हैं।",
  "Each agent": "हर एजेंट",
  "Each agent belongs to one app. For another app or device, make a new agent.": "हर एजेंट एक ऐप का होता है। दूसरे ऐप या डिवाइस के लिए नया एजेंट बनाएँ।",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "हर एजेंट एक ऐप का होता है। Memora को दूसरे ऐप में इस्तेमाल करने के लिए उसके लिए अलग एजेंट बनाएँ।",
  "Each app gets its own key": "हर ऐप को अपनी कुंजी मिलती है",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "हर एक की एक छोटी आईडी है जो कभी नहीं बदलती, इसलिए नाम बेझिझक बदले जा सकते हैं। Mnemo उन्हें बनाता है, उनके निर्देश या मॉडल बदलता है, संदेश भेजता है, इंतज़ार करता है, रोकता है, पूरा करता है और हटाता है, एक-एक करके या सब एक साथ, और उन्हें पृष्ठभूमि में काम करने दे सकता है। हर कार्ड निर्देश, गतिविधि और उत्तर दिखाता है।",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "हर प्रकार को उसकी अपनी जगह के मुकाबले नापा जाता है: सेट हो तो उसकी सीमा, नहीं तो जितना वह लेता है उसमें खाली डिस्क जगह{disk} जोड़कर। सीमा खाली: कोई नहीं।",
  "Each one gets its own key from Memora.": "हर एक को Memora से अपनी कुंजी मिलती है।",
