  "Embed new or existing boards in a note and work on each right there, or put a board into any note from its ⋯ menu; a plain link reads as a small card.": "नए या मौजूदा बोर्ड किसी नोट में एम्बेड करें और हर एक पर वहीं काम करें, या किसी भी नोट के ⋯ मेन्यू से उसमें बोर्ड डालें; सादा लिंक एक छोटे कार्ड जैसा दिखता है।",
