  "From now on, whenever I tell you something important, save it into Memora. Try it now: save a note that I started using Memora today.": "अब से जब भी मैं कोई ज़रूरी बात बताऊँ, उसे Memora में सहेजो। अभी आज़माओ: एक नोट सहेजो कि मैंने आज Memora इस्तेमाल करना शुरू किया।",
