  "Gathering the real activity for {range}. This can take a moment on a big log, please wait.": "{range} की असली गतिविधि इकट्ठी की जा रही है। बड़े लॉग में कुछ समय लग सकता है, कृपया रुकें।",
  "General": "सामान्य",
  "Get a one-time code on the server": "सर्वर पर वन-टाइम कोड पाएँ",
  "Get started": "शुरू करें",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "मेरे नोट से मुझे जानो। मेरा वॉल्ट देखो (हाल के नोट, डायरी, प्रोजेक्ट, मेरे बारे में कुछ भी) और जो सीखो उसे remember_owner से रखो: मैं कौन हूँ, किस पर काम करता हूँ, जवाब कैसे पसंद करता हूँ, मुझे क्या पसंद है। सिर्फ़ छोटी, टिकने वाली बातें, राज़ कभी नहीं। फिर कुछ पंक्तियों में बताओ कि तुमने क्या रखा।",
  "Gets its own agent key: read and write nodes over MCP": "अपनी एजेंट कुंजी मिलती है: MCP पर नोड पढ़ें और लिखें",
  "Getting started": "शुरुआत करना",
  "GitHub answered HTTP {code}": "GitHub ने HTTP {code} दिया",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Claude, Cursor या किसी भी MCP ऐप को अपनी कुंजी दें, फिर उसे वह सहेजने दें जो वह आपके बारे में पहले से जानता है।",
  "Give a key read-only access, or let it write too.": "कुंजी को सिर्फ़ पढ़ने का एक्सेस दें, या लिखने भी दें।",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "हर ऐप या डिवाइस को अपना एजेंट दें। तब गतिविधि ठीक-ठीक दिखाती है कि किसने क्या किया, और आप बाकी को छुए बिना किसी एक को बंद कर सकते हैं।",
  "Give it a name you recognise": "ऐसा नाम दें जो आप पहचानें",
  "Give the agent a name": "एजेंट को नाम दें",
