  "How Memora looks for you. Saved in this browser only.": "आपके लिए Memora कैसा दिखे। सिर्फ़ इस ब्राउज़र में सहेजा जाता है।",
  "How far apart the folder islands of the Clusters layout are.": "Clusters लेआउट के फ़ोल्डर द्वीप एक-दूसरे से कितने दूर हैं।",
