  "How full notes, images and chats are, and their limits": "नोट, तस्वीरें और चैट कितने भरे हैं, और उनकी सीमाएँ",
  "How hard notes push each other apart in the Force layout.": "Force लेआउट में नोट एक-दूसरे को कितनी ज़ोर से दूर धकेलते हैं।",
