  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "नोट, तस्वीरें और Mnemo चैट कितनी जगह लेते हैं, हर एक अपनी जगह के मुकाबले। कोई लगभग भर जाए तो बैनर चेतावनी देता है।",
  "How the agent itself shows up: its display name and colour.": "एजेंट खुद कैसा दिखता है: उसका दिखने वाला नाम और रंग।",
  "How to update": "अपडेट कैसे करें",
  "How {mnemo} works": "{mnemo} कैसे काम करता है",
