  "Hyphenate long words": "लंबे शब्दों को हाइफ़न से तोड़ें",
  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "मैं आपके नोट खोजता, पढ़ता, लिखता, टैग करता, जोड़ता और व्यवस्थित करता हूँ। न वेब, न शेल: सिर्फ़ आपका वॉल्ट।",
  "Icon": "आइकन",
  "Icon {name}": "आइकन {name}",
  "Ideas grow when they connect. Link this note to {a} or read {b}.": "विचार जुड़ने पर बढ़ते हैं। इस नोट को {a} से लिंक करें या {b} पढ़ें।",
  "Identity": "पहचान",
  "Idle": "खाली",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "अगर यह आपके काम आया हो, तो GitHub पर एक स्टार या किसी दोस्त को बताना दूसरों को इसे खोजने में मदद करता है। न करें तो कोई बात नहीं।",
  "If you leave, they are kept on this device and offered again when you open the note.": "आप छोड़ दें तो वे इस डिवाइस पर रखे जाते हैं और नोट खोलने पर फिर पेश किए जाते हैं।",
  "Image": "तस्वीर",
  "Image (or paste or drop one)": "तस्वीर (या पेस्ट करें या छोड़ें)",
