  "Images can now be up to {n} MB": "तस्वीरें अब {n} MB तक हो सकती हैं",
  "Images in this folder": "इस फ़ोल्डर की तस्वीरें",
  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "तस्वीरें उन नोट के पास रहती हैं जो उन्हें दिखाते हैं। चुनें कि एक तस्वीर कितनी बड़ी हो सकती है, और देखें कि नोट और तस्वीरें कितनी जगह लेते हैं।",
  "Import and export": "इंपोर्ट और एक्सपोर्ट",
  "Imported": "इंपोर्ट हुआ",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "ChatGPT में <b>Settings → Apps &amp; Connectors → Advanced settings</b> खोलें और <b>Developer mode</b> चालू करें। फिर <b>Create</b> चुनें।",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "Claude (वेब या डेस्कटॉप) में <b>Settings → Connectors</b> खोलें और <b>Add custom connector</b> चुनें।",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "Claude Desktop में <b>Settings → Developer → Edit Config</b> खोलें। नए वर्शन में इसके बजाय <b>Claude</b> चुनें।",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "Windsurf में <b>Settings → Cascade → MCP servers</b> खोलें और <b>View raw config</b> चुनें।",
