  "Make an agent for each app or device you use. Each one gets its own key, so you can see what it does and turn it off on its own.": "आप जो भी ऐप या डिवाइस इस्तेमाल करें, उसके लिए एक एजेंट बनाएँ। हर एक को अपनी कुंजी मिलती है, इसलिए आप देख सकते हैं कि वह क्या करता है और उसे अलग से बंद कर सकते हैं।",
  "Make an index note for my biggest folder": "मेरे सबसे बड़े फ़ोल्डर के लिए इंडेक्स नोट बनाओ",
