  "Meet Mnemo, your notes agent": "मिलिए Mnemo से, आपके नोट एजेंट",
  "Memora address (MCP endpoint)": "Memora पता (MCP एंडपॉइंट)",
  "Memora already uses this folder.": "Memora यह फ़ोल्डर पहले से इस्तेमाल करता है।",
  "Memora by Codrihub Tech": "Memora, Codrihub Tech की ओर से",
  "Memora can save notes here": "Memora यहाँ नोट सहेज सकता है",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora फ़ोल्डर जाँचता है और बदलने से पहले आपसे पुष्टि माँगता है। कुछ ले जाया या कॉपी नहीं होता, और आप यहीं वापस बदल सकते हैं। Docker में चला रहे हैं? कंटेनर में माउंट किया फ़ोल्डर इस्तेमाल करें।",
  "Memora could not start.": "Memora शुरू नहीं हो सका।",
  "Memora data folder": "Memora डेटा फ़ोल्डर",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora पहले जाँचता है कि नया फ़ोल्डर मौजूद है (या बन सकता है) और वह वहाँ नोट सहेज सकता है। जाँच विफल हो तो कुछ नहीं बदलता।",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora पहले जाँचता है कि नया फ़ोल्डर मौजूद है और वह वहाँ नोट सहेज सकता है। जाँच विफल हो तो कुछ नहीं बदलता।",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "आपकी भाषा में Memora, काम करते हुए अपनी योजना दिखाता Mnemo, और आप चुनते हैं कि वह क्या इस्तेमाल करे और देखे।",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora एक नोट ऐप है जिसे आपके AI ऐप भी इस्तेमाल कर सकते हैं। आप इसमें लिखते हैं, वे वही नोट पढ़ते और लिखते हैं, और आप हमेशा देख सकते हैं कि क्या बदला।",
  "Memora is free and open source": "Memora मुफ़्त और ओपन सोर्स है",
  "Memora is free and open source. A star helps others find it.": "Memora मुफ़्त और ओपन सोर्स है। एक स्टार दूसरों को इसे खोजने में मदद करता है।",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora उन्नत मेमोरी है: यह याद रखने के लिए बना है कि आप और आपका AI क्या सीखते हैं, और जितना इस्तेमाल करें उतना ज़्यादा याद रखता है।",
  "Memora is restarting": "Memora फिर शुरू हो रहा है",
  "Memora is shut down": "Memora बंद हो गया है",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora अभी खाली है। कोई AI ऐप जोड़ें, उसे एक प्रॉम्प्ट भेजें, और वह आपके बारे में जो जानता है उसे यहाँ नोट के रूप में सहेजता है, जिन्हें आप पढ़, बदल और ब्रेन में देख सकते हैं।",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora आपके टैग की एक सूची रखता है ताकि टाइप करते समय सुझा सके। कोई टैग न दिखे या पुराना हो तो इसे रीफ़्रेश करें।",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "वॉल्ट फ़ोल्डर git रिपॉज़िटरी हो तो Memora नोट का हर वर्शन रखता है। वॉल्ट फ़ोल्डर में एक बार {cmd} चलाएँ (डॉक्स में Configuration, “Version history” देखें); तब से हर बदलाव यहाँ रखा जाता है।",
  "Memora keeps it in one place:": "Memora इसे एक ही जगह रखता है:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora हर नोट को जिस मशीन पर चलता है वहाँ सादी Markdown फ़ाइल के रूप में सहेजता है। कुछ भी बँधा नहीं है: फ़ाइलें किसी भी एडिटर में खोलें, उनका बैकअप लें, या Git में रखें।",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora streamable HTTP पर MCP बोलता है। ऐप कुंजी को हेडर <code>Authorization: Bearer &lt;key&gt;</code> में भेजते हैं।",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora जिस मशीन पर चलता है वहीं बंद हो जाता है। आपके नोट डिस्क पर सुरक्षित रहते हैं।",
  "Memora version": "Memora वर्शन",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} उपलब्ध है। यह सर्वर v{current} चला रहा है।",
  "Memora, open Overview": "Memora, ओवरव्यू खोलें",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: आपका खुद होस्ट किया नोट वॉल्ट, जिसे व्यवस्थित रखने वाला एक एजेंट साथ है।",
