  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "हर चौड़ाई में संदेश और संदेश बॉक्स बिल्कुल एक सीध में, मॉडल चुनने की अपनी सतह, फ़्लीटिंग चैट फ़ोन पर फ़िट, और टैप करते समय प्रश्न के विकल्प खिसकते नहीं।",
  "Middle-drag": "बीच बटन से खींचें",
  "Midnight": "मध्यरात्रि",
  "Minimap": "मिनीमैप",
  "Minimap: click or drag to move the view": "मिनीमैप: व्यू हिलाने के लिए क्लिक या ड्रैग करें",
  "Mist": "धुंध",
  "Mnemo (AI agent)": "Mnemo (AI एजेंट)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Mnemo और एजेंट बोर्ड पर वह सब कर सकते हैं जो आप कर सकते हैं, MCP के ज़रिए, चार कानबन अनुमति स्विच के पीछे जो पहले पूछें, ऑटो और सिर्फ़ पढ़ना का पालन करते हैं।",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Mnemo बटन छिपा है। इसे फिर दिखाने के लिए और, Mnemo बटन दिखाएँ में जाएँ।",
  "Mnemo goes on without sub-agents": "Mnemo सब-एजेंट के बिना आगे बढ़ता है",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemo के पास अभी कोई मॉडल नहीं है: सेटिंग्स, Mnemo में प्रोवाइडर और उसके मॉडल जोड़ें",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo Memora में ही बना है। अपनी AI कुंजी जोड़ें, फिर सीधे शब्दों में पूछें: वह आपके लिए नोट खोजता, लिखता, टैग करता, जोड़ता और व्यवस्थित करता है।",
  "Mnemo is still answering in this chat": "Mnemo इस चैट में अभी जवाब दे रहा है",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo, Memora में बना एजेंट है। अपनी AI कुंजी जोड़ें और सीधे शब्दों में कहें: यह आपके नोट व्यवस्थित रखता है, जबकि आपके दूसरे ऐप उनका उपयोग करते हैं।",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo अधिकतम {n} प्रोवाइडर रखता है; पहले एक हटाएँ",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo अपने सब-एजेंट संभालता है, अपनी योजना चैट के साथ रखता है, और चैट हर स्क्रीन पर बेहतर बैठती है।",
  "Mnemo runs its sub-agents": "Mnemo अपने सब-एजेंट चलाता है",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo {n} चरणों के बाद रुक गया; आगे बढ़ाने के लिए \"continue\" कहें।",
  "Mnemo's plan, live": "Mnemo की योजना, लाइव",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "Mnemo का प्रश्न अपनी अलग पट्टी पर होता है, नीचे उत्तर टैप करने वाली पंक्तियों में, जितने प्रश्न को चाहिए।",
  "Mnemo, your notes agent": "Mnemo, आपका नोट एजेंट",
