  "Models, keys and instructions": "मॉडल, कुंजियाँ और निर्देश",
  "Money": "पैसे",
  "Mono": "मोनो",
  "More": "और",
  "More actions": "और कार्रवाइयाँ",
  "More actions for {name}": "{name} की और कार्रवाइयाँ",
  "More cards than the limit of {n}": "{n} की सीमा से ज़्यादा कार्ड",
  "More instruction styles": "और निर्देश शैलियाँ",
  "More on phones": "फ़ोन पर और",
  "More: export, all activity": "और: एक्सपोर्ट, सारी गतिविधि",
  "More: reload, export": "और: रीलोड, एक्सपोर्ट",
  "More: rename, move, colour, delete": "और: नाम बदलें, ले जाएँ, रंग, हटाएँ",
  "More: rename, move, pin, delete": "और: नाम बदलें, ले जाएँ, पिन, हटाएँ",
  "Most AI apps start each chat from nothing, and each keeps its own memory. With Memora, Claude, Cursor and any other app that speaks MCP read and write the same notes, so what one app learns, the others can use.": "ज़्यादातर AI ऐप हर चैट शून्य से शुरू करते हैं, और हर एक की अपनी अलग मेमोरी होती है। Memora के साथ Claude, Cursor और MCP बोलने वाला कोई भी ऐप वही नोट पढ़ता और लिखता है, इसलिए एक ऐप जो सीखता है, बाकी उसे इस्तेमाल कर सकते हैं।",
  "Most cards in this lane (0 for no limit)": "इस कॉलम में ज़्यादा से ज़्यादा कार्ड (0 यानी कोई सीमा नहीं)",
