  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "नहीं हुआ: Mnemo पहले पूछें मोड में है, इसलिए बदलाव मालिक की मंज़ूरी का इंतज़ार करते हैं। ask_owner से पूछें (बताएँ कि क्या बदलेंगे; approve: true वाला विकल्प दें जैसे \"Yes, go ahead\"), फिर मंज़ूरी के बाद बदलाव करें।",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "नहीं हुआ: Mnemo सिर्फ़ पढ़ने के मोड में है, इसलिए नोट नहीं बदले जाते। बताएँ कि क्या बदलते; मालिक चैट में पहले पूछें या ऑटो पर जा सकता है।",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "नहीं हुआ: चैट पहले पूछें मोड में है, इसलिए सब-एजेंट नोट नहीं बदल सकता। अपने जवाब में बताएँ कि क्या बदलना चाहिए; Mnemo मालिक से पूछेगा।",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "नहीं हुआ: मालिक ने Mnemo के लिए {tool} बंद किया है (सेटिंग्स, Mnemo)।",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "नहीं हुआ: मालिक ने सब-एजेंट के लिए {tool} बंद किया है (सेटिंग्स, Mnemo)।",
  "Not finished: the owner cut this reply before the tool returned.": "पूरा नहीं हुआ: टूल के लौटने से पहले मालिक ने यह जवाब काट दिया।",
