  "Not started: there is no model \"{name}\" here. Tell the owner, or leave model out to use their default model.": "शुरू नहीं हुआ: यहाँ \"{name}\" नाम का कोई मॉडल नहीं है। मालिक को बताएँ, या उनका डिफ़ॉल्ट मॉडल इस्तेमाल करने के लिए मॉडल छोड़ दें।",
