  "Notes": "नोट",
  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "नोट और बोर्ड फ़ोन, टैबलेट और डेस्कटॉप पर एक जैसी स्पेसिंग वाला एक ही पेज फ़्रेम इस्तेमाल करते हैं, और नोट के नीचे के लिंक एक जैसे साफ़-सुथरे रूप में दिखते हैं जिन्हें समेटा जा सकता है।",
  "Notes and boards, connected": "नोट और बोर्ड, आपस में जुड़े",
  "Notes and images in the notes folder.": "नोट फ़ोल्डर के नोट और तस्वीरें।",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "नोट और उनके बीच के लिंक यहाँ नक्शे के रूप में दिखते हैं। गाइड बताती है कि AI से अपना ज्ञान यहाँ कैसे सहेजवाएँ, या खुद नोट कैसे लिखें।",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "AI के सहेजते ही नोट दिखते हैं और ब्रेन को रोशन करते हैं। पहला नोट आते ही यह पेज आपका डैशबोर्ड बन जाता है।",
  "Notes are not a password manager.": "नोट पासवर्ड मैनेजर नहीं हैं।",
  "Notes changed in the app or in the folder": "ऐप या फ़ोल्डर में बदले नोट",
  "Notes folder": "नोट फ़ोल्डर",
  "Notes folder switched": "नोट फ़ोल्डर बदला गया",
  "Notes from {name}": "{name} के नोट",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "Obsidian Kanban फ़ॉर्मैट वाले नोट बोर्ड के रूप में खुलते हैं। माउस या उँगली से कार्ड और कॉलम खींचें, और हर बदलाव नोट के इतिहास में दर्ज होता है।",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "मौजूदा फ़ोल्डर के नोट न ले जाए जाते हैं, न कॉपी होते हैं, न हटते हैं। आप यहीं कभी भी वापस बदल सकते हैं।",
