  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "अभी कुछ छिपा नहीं: जिन एजेंट से छिपाना है उन्हें टिक करें। अभी एकमात्र एजेंट इसे देख सकता है।",
  "Nothing in 24h": "24 घंटे में कुछ नहीं",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "नोट के नाम, फ़ोल्डर या टेक्स्ट में कुछ नहीं, और इससे मिलती-जुलती वर्तनी का भी कुछ नहीं। कम अक्षर, दूसरी वर्तनी, या नोट के अंदर का कोई शब्द आज़माएँ।",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "पिछले 24 घंटे में कुछ नहीं। आपके AI जो करते हैं वह होते ही यहाँ दिखता है।",
  "Nothing in the log goes by “{name}”. Showing all activity.": "लॉग में “{name}” नाम का कुछ नहीं है। सारी गतिविधि दिखाई जा रही है।",
  "Nothing in this range": "इस सीमा में कुछ नहीं",
  "Nothing in your chats says “{query}”.": "आपकी चैट में “{query}” कहीं नहीं है।",
