  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "कुछ नहीं खोता: मौजूदा टेक्स्ट इतिहास में v{n} के रूप में रहता है, इसलिए आप कभी भी वापस जा सकते हैं।",
  "Nothing links here yet.": "अभी कुछ यहाँ लिंक नहीं करता।",
