  "Optional. A few words on who you are, what you work on, how you like answers. {mnemo} keeps them and you can change them any time in Settings.": "वैकल्पिक। कुछ शब्द कि आप कौन हैं, किस पर काम करते हैं, जवाब कैसे पसंद हैं। {mnemo} इन्हें रखता है और आप इन्हें कभी भी सेटिंग्स में बदल सकते हैं।",
