  "Other servers in the file already? Add only the <code>memora</code> entry inside <code>mcpServers</code>.": "फ़ाइल में पहले से दूसरे सर्वर हैं? सिर्फ़ <code>memora</code> प्रविष्टि <code>mcpServers</code> के अंदर जोड़ें।",
