  "Pages {mnemo} writes, and the notes, folders and images this chat attaches, reads, changes or shows you collect here.": "{mnemo} जो पेज लिखता है, और यह चैट जो नोट, फ़ोल्डर और तस्वीरें जोड़ती, पढ़ती, बदलती या दिखाती है, वे यहाँ इकट्ठे होते हैं।",
