  "Password changed. {n} other device signed out.": "पासवर्ड बदला गया। {n} दूसरा डिवाइस साइन आउट हुआ।",
  "Password changed. {n} other devices signed out.": "पासवर्ड बदला गया। {n} दूसरे डिवाइस साइन आउट हुए।",
  "Password must be at least {min} characters.": "पासवर्ड कम से कम {min} अक्षर का होना चाहिए।",
  "Password saved. Opening your vault...": "पासवर्ड सहेजा गया। आपका वॉल्ट खुल रहा है...",
  "Password saved. Sign in with the new password.": "पासवर्ड सहेजा गया। नए पासवर्ड से साइन इन करें।",
  "Passwords are reset on the server that runs Memora.": "पासवर्ड उसी सर्वर पर रीसेट होते हैं जो Memora चलाता है।",
  "Passwords do not match": "पासवर्ड मेल नहीं खाते",
  "Passwords do not match.": "पासवर्ड मेल नहीं खाते।",
  "Passwords match": "पासवर्ड मेल खाते हैं",
  "Past activity keeps the old name; new activity uses this one.": "पुरानी गतिविधि पुराना नाम रखती है; नई गतिविधि यह इस्तेमाल करती है।",
  "Paste both into the app and save.": "दोनों को ऐप में पेस्ट करें और सहेजें।",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "इसे टर्मिनल में पेस्ट करके <kbd>Enter</kbd> दबाएँ, फिर उसी टर्मिनल में Codex शुरू करें।",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "इसे टर्मिनल में पेस्ट करके <kbd>Enter</kbd> दबाएँ। फिर Claude Code शुरू करें, या उसे रीस्टार्ट करें: Memora अपने आप लोड होता है।",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "इसे टर्मिनल में पेस्ट करके <kbd>Enter</kbd> दबाएँ। फिर Gemini CLI शुरू करें, या रीस्टार्ट करें, और Memora देखने के लिए <code>/mcp</code> टाइप करें।",
  "Paste it into the app where it asks for a key.": "इसे ऐप में वहाँ पेस्ट करें जहाँ वह कुंजी माँगे।",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "इसे फ़ाइल में पेस्ट करके सहेजें, फिर <b>Refresh</b> दबाएँ। Memora सूची में दिखेगा।",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "इसे फ़ाइल में पेस्ट करें, सहेजें, और Claude Desktop रीस्टार्ट करें। इसके लिए इस कंप्यूटर पर Node.js चाहिए।",
  "Paste it into {app}": "इसे {app} में पेस्ट करें",
  "Paste the API key": "API कुंजी पेस्ट करें",
  "Paste these once where {app} reads its standing instructions, so it uses Memora in every conversation, not only when asked.": "इन्हें एक बार वहाँ पेस्ट करें जहाँ {app} अपने स्थायी निर्देश पढ़ता है, ताकि वह हर बातचीत में Memora इस्तेमाल करे, सिर्फ़ कहने पर नहीं।",
