  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "मैंने अपने निजी जीवन के बारे में जो तुम्हें बताया है उसे Memora में सहेजो: मेरी रुचियाँ, आदतें, लक्ष्य, मेरे लिए ज़रूरी लोग और जिन चीज़ों की मुझे परवाह है। ये नोट Private नाम के फ़ोल्डर में रखो, हर विषय का एक नोट, और संबंधित नोट जोड़ो। पासवर्ड, कार्ड नंबर या दूसरे राज़ कभी मत सहेजो। पूरा होने पर बताओ कि तुमने क्या सहेजा।",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "मेरे काम के बारे में जो तुम जानते हो उसे Memora में सहेजो: मेरी भूमिका, मेरी टीम, जिन प्रोजेक्ट पर हूँ और वे कहाँ तक पहुँचे, और हमारे लिए गए फ़ैसले। हर प्रोजेक्ट या विषय का एक नोट बनाओ और उन्हें आपस में जोड़ो।",
