  "This keeps out everyone that no rule above it lets in, including you, unless a rule allowing your own address comes first.": "यह उन सबको बाहर रखता है जिन्हें इसके ऊपर का कोई नियम अंदर नहीं आने देता, आपको भी, जब तक आपके अपने पते को अनुमति देने वाला नियम पहले न आए।",
  "This key is shown once. Copy it now and keep it private.": "यह कुंजी एक बार दिखाई जाती है। इसे अभी कॉपी करें और निजी रखें।",
  "This model cannot read pictures": "यह मॉडल चित्र नहीं पढ़ सकता",
  "This note": "यह नोट",
  "This note does not link to other notes yet.": "यह नोट अभी दूसरे नोट से लिंक नहीं करता।",
  "This note does not link to other notes yet. Type [[ while editing to add a link.": "यह नोट अभी दूसरे नोट से लिंक नहीं करता। लिंक जोड़ने के लिए बदलते समय [[ टाइप करें।",
  "This note has changes that are not saved yet.": "इस नोट में ऐसे बदलाव हैं जो अभी सहेजे नहीं गए।",
  "This note has its own settings, which win over these.": "इस नोट की अपनी सेटिंग्स हैं, जो इनसे ऊपर हैं।",
  "This note has no headings yet.": "इस नोट में अभी कोई शीर्षक नहीं।",
  "This note has not been saved to the history yet. The next change starts it.": "यह नोट अभी इतिहास में सहेजा नहीं गया। अगला बदलाव इसे शुरू करता है।",
  "This note is a board now": "यह नोट अब एक बोर्ड है",
  "This note is empty.": "यह नोट खाली है।",
  "This note is empty. {start} or press {key}.": "यह नोट खाली है। {start} या {key} दबाएँ।",
  "This note is removed from the vault for good, with its text, tags and links. Every earlier version is erased from the version history too, so no one, agents included, can read it again.": "यह नोट अपने टेक्स्ट, टैग और लिंक के साथ वॉल्ट से हमेशा के लिए हट जाता है। हर पुराना वर्शन भी वर्शन इतिहास से मिट जाता है, इसलिए एजेंट समेत कोई भी इसे दोबारा नहीं पढ़ सकता।",
  "This note links to nothing yet.": "यह नोट अभी कहीं लिंक नहीं करता।",
  "This note only": "सिर्फ़ यह नोट",
  "This note shows no image of its folder yet.": "यह नोट अभी अपने फ़ोल्डर की कोई तस्वीर नहीं दिखाता।",
  "This notes folder is empty": "यह नोट फ़ोल्डर खाली है",
  "This page continues on its own when the pause ends.": "रुकावट खत्म होने पर यह पेज अपने आप आगे बढ़ता है।",
  "This page moves on by itself.": "यह पेज अपने आप आगे बढ़ जाता है।",
  "This page notices by itself as soon as {app} connects. Keep it open.": "{app} के जुड़ते ही यह पेज अपने आप पता लगा लेता है। इसे खुला रखें।",
  "This server is run by systemd, which starts it again a few seconds later. To keep it stopped, run {cmd} on the server instead.": "यह सर्वर systemd चलाता है, जो इसे कुछ सेकंड बाद फिर शुरू कर देता है। इसे बंद रखने के लिए इसके बजाय सर्वर पर {cmd} चलाएँ।",
  "This server runs in Docker, which may start it again. To keep it stopped, run {cmd} on the host instead.": "यह सर्वर Docker में चलता है, जो इसे फिर शुरू कर सकता है। इसे बंद रखने के लिए इसके बजाय होस्ट पर {cmd} चलाएँ।",
  "This vault has no tags yet. Add {inline} or a {line} line to a note.": "इस वॉल्ट में अभी कोई टैग नहीं। किसी नोट में {inline} या {line} पंक्ति जोड़ें।",
  "This vault is private. Sign in to see your notes, the brain and agent activity.": "यह वॉल्ट निजी है। अपने नोट, ब्रेन और एजेंट गतिविधि देखने के लिए साइन इन करें।",
  "Thought it through": "ठीक से सोचा",
