  "Too many requests. Wait a few seconds and try again.": "बहुत ज़्यादा अनुरोध। कुछ सेकंड रुकें और फिर कोशिश करें।",
  "Too many wrong codes, so this reset code no longer works. Run memora-cli reset-password on the server for a new one.": "बहुत ज़्यादा गलत कोड, इसलिए यह रीसेट कोड अब काम नहीं करता। नया पाने के लिए सर्वर पर memora-cli reset-password चलाएँ।",
  "Too many wrong codes, so this setup code no longer works. Run memora-cli setup on the server for a new one.": "बहुत ज़्यादा गलत कोड, इसलिए यह सेटअप कोड अब काम नहीं करता। नया पाने के लिए सर्वर पर memora-cli setup चलाएँ।",
