  "Tools run under the name {mnemo} so every action shows in Activity. Tap a tool to switch it off or on, for {mnemo} itself or for its sub-agents. A tool switched off on the Tools page is off for both. Saved at once.": "टूल {mnemo} नाम से चलते हैं ताकि हर कार्रवाई गतिविधि में दिखे। किसी टूल को बंद या चालू करने के लिए उस पर टैप करें, {mnemo} के लिए या उसके सब-एजेंट के लिए। टूल पेज पर बंद किया टूल दोनों के लिए बंद है। तुरंत सहेजा जाता है।",
