  "You now have long-term memory through Memora. Save into Memora everything you know about me from our conversations: who I am, my work, the projects I'm on, my preferences and important decisions. Make one note per topic in a fitting folder, and link notes that belong together. When you're done, tell me what you saved.": "अब Memora के ज़रिए तुम्हारे पास लंबी अवधि की मेमोरी है। हमारी बातचीत से मेरे बारे में जो कुछ तुम जानते हो वह सब Memora में सहेजो: मैं कौन हूँ, मेरा काम, जिन प्रोजेक्ट पर हूँ, मेरी पसंद और ज़रूरी फ़ैसले। हर विषय का एक नोट किसी सही फ़ोल्डर में बनाओ, और जो नोट साथ के हैं उन्हें जोड़ो। पूरा होने पर बताओ कि तुमने क्या सहेजा।",
