  "with this on, the agent can turn tools back on, widen its own permissions and make or delete other agents. Only for automation you fully trust.": "इसके चालू होने पर एजेंट टूल फिर चालू कर सकता है, अपनी अनुमतियाँ बढ़ा सकता है और दूसरे एजेंट बना या हटा सकता है। सिर्फ़ ऐसे ऑटोमेशन के लिए जिस पर आप पूरा भरोसा करते हैं।",
