  "{app} gets its own agent and key. The key is made when you continue.": "{app} को अपना एजेंट और कुंजी मिलती है। कुंजी आपके जारी रखने पर बनती है।",
  "{app} laptop": "{app} लैपटॉप",
  "{app} opens a Memora page in your browser to ask for permission. If you closed it, start again from step 1.": "{app} अनुमति माँगने के लिए आपके ब्राउज़र में Memora का पेज खोलता है। उसे बंद कर दिया हो तो चरण 1 से फिर शुरू करें।",
  "{app} signs in with your Memora account and shows up as its own agent.": "{app} आपके Memora खाते से साइन इन करता है और अपने एजेंट के रूप में दिखता है।",
