  "{kind} storage is almost full: {pct}% used.": "{kind} स्टोरेज लगभग भर गया है: {pct}% इस्तेमाल।",
  "{kind} storage is full ({pct}% of {room}). {advice}": "{kind} स्टोरेज भर गया है ({room} का {pct}%)। {advice}",
