  "{mnemo} activity": "{mnemo} की गतिविधि",
  "{mnemo} asks": "{mnemo} पूछता है",
  "{mnemo} asks before sub-agents run": "सब-एजेंट चलाने से पहले {mnemo} पूछता है",
  "{mnemo} asks this model when you want a picture made.": "जब आप तस्वीर बनवाना चाहें तो {mnemo} इस मॉडल से कहता है।",
  "{mnemo} button hidden. Bring it back from More, Show the {mnemo} button.": "{mnemo} बटन छिपा है। इसे और, {mnemo} बटन दिखाएँ से वापस लाएँ।",
  "{mnemo} button hidden. Show it again here or from More.": "{mnemo} बटन छिपा है। इसे यहाँ या और से फिर दिखाएँ।",
  "{mnemo} could not write new ones just now. Check the model in Settings.": "{mnemo} अभी नए नहीं लिख सका। सेटिंग्स में मॉडल जाँचें।",
  "{mnemo} hands pictures to this model when the chat model cannot see.": "जब चैट मॉडल तस्वीरें नहीं देख सकता तो {mnemo} तस्वीरें इस मॉडल को देता है।",
  "{mnemo} is working on this": "{mnemo} इस पर काम कर रहा है",
  "{mnemo} keeps only what you add": "{mnemo} सिर्फ़ वही रखता है जो आप जोड़ें",
  "{mnemo} knows nothing about you yet.": "{mnemo} अभी आपके बारे में कुछ नहीं जानता।",
  "{mnemo} looks after your notes": "{mnemo} आपके नोट की देखभाल करता है",
  "{mnemo} may learn about you": "{mnemo} आपके बारे में सीख सकता है",
  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} सिर्फ़ आपके नोट में काम करता है। हर बदलाव गतिविधि में दिखता है और इतिहास से पूर्ववत हो सकता है।",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} नई चैट में आपका वॉल्ट पढ़ता है और जो सीखता है उसे यहाँ रखता है।",
  "{mnemo} settings saved": "{mnemo} सेटिंग्स सहेजी गईं",
  "{mnemo} settings: models and keys": "{mnemo} सेटिंग्स: मॉडल और कुंजियाँ",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "जब कोई काम अच्छी तरह बँट सकता है तो {mnemo} सब-एजेंट खुद शुरू करता है; कुछ सेट करने की ज़रूरत नहीं। वे आपके डिफ़ॉल्ट मॉडल पर चलते हैं, फिर फ़ॉलबैक पर, जब तक आप चैट में कोई मॉडल न बताएँ। उन्हें चैट के ऊपर दाएँ एजेंट में देखें और उनका मॉडल बदलें। वे अपने टोकन इस्तेमाल करते हैं, इसलिए पहले पूछें में {mnemo} पूछता है और बताता है कि लगभग कितने; ऑटो में वे बस चलते हैं। तुरंत सहेजा जाता है।",
  "{mnemo} stopped it": "{mnemo} ने इसे रोका",
  "{mnemo} will keep that in mind": "{mnemo} इसे ध्यान में रखेगा",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "{mnemo} आपके हाल के नोट से नए सुझाव लिखता है (आपके अपने रहते हैं)",
  "{mnemo}'s own ({n})": "{mnemo} के अपने ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "आपसे कैसे बात करनी है इस पर {mnemo} के अपने नोट, हर चैट में पढ़े जाते हैं। बदलने के लिए किसी पर क्लिक करें।",
  "{mnemo}, your notes agent": "{mnemo}, आपका नोट एजेंट",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} तस्वीरें नहीं देख सकता; उसे इसके बजाय उनके नाम मिले। उन्हें दिखाने के लिए सेटिंग्स में तस्वीरें पढ़ने वाला मॉडल सेट करें।",
  "{model} cannot look at images; the image model described them for it.": "{model} तस्वीरें नहीं देख सकता; तस्वीर मॉडल ने उसके लिए उनका वर्णन किया।",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} तस्वीरें नहीं पढ़ सकता, इसलिए उसे सिर्फ़ उनके नाम मिलते हैं। तस्वीरें पढ़ने वाला मॉडल सेट करें, या इस चैट का मॉडल बदलें।",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} तस्वीरें नहीं पढ़ सकता, इसलिए उसे सिर्फ़ उनके नाम मिले। तस्वीरें पढ़ने वाला मॉडल सेट करें, या इस चैट का मॉडल बदलें।",
  "{model} cannot read pictures, so the image model looked at them for it.": "{model} तस्वीरें नहीं पढ़ सकता, इसलिए तस्वीर मॉडल ने उसके लिए उन्हें देखा।",
  "{model} cannot read pictures, so the image model looks at them for it.": "{model} तस्वीरें नहीं पढ़ सकता, इसलिए तस्वीर मॉडल उसके लिए उन्हें देखता है।",
  "{model} did not answer ({why}); trying again in {wait} s ({n}/{total})…": "{model} ने जवाब नहीं दिया ({why}); {wait} s में फिर कोशिश ({n}/{total})…",
